
/* Hidden surprise flow: About (neutral entry) -> mystery popup -> YES: cinematic transition -> dedication page | NO: relief message -> return -> popup. */
window.SHB_DED_PHOTO="data:image/jpeg;base64,";
window.SHB_DED_HEART="data:image/png;base64,";
function dedicationView(){return `${appHeader('Dedication')}<div class="rs ded-pg"><i class="ded-glow" aria-hidden="true"></i>
 <p class="ded-kick" dir="ltr">A SPECIAL DEDICATION</p>
 <header class="ded-hero"><span class="ded-heartwrap" aria-hidden="true"><img class="ded-heart" src="${window.SHB_DED_HEART}" alt="" width="400" height="563" decoding="sync"></span><h2 class="ded-t2" dir="rtl">إلى دفعة الصمود والاحترام</h2></header>
 <p class="ded-s2" dir="rtl">دفعة العزم والإصرار | دفعة 52 | مفاضلة 7</p>
 <figure class="ded-photo"><img src="${window.SHB_DED_PHOTO}" alt="Batch 52 group photograph" decoding="sync"></figure>
 <p class="ded-sec" dir="ltr"><span>THE OFFICIAL DEDICATION</span></p>
 <article class="ded-ed"><div class="ded-rv ded-opening"><p class="en en-open">Ladies and Gentlemen…</p></div><div class="ded-rv "><p class="ar ">بعد مراجعة شاملة للأحداث، ودراسة مستفيضة للظروف، و<mark class="hl">النظر في عددٍ من الملفات التي لم يطلب أحد فتحها أصلاً</mark>، تقرر إصدار هذا الإهداء الرسمي إلى دفعة الصمود والاحترام.</p></div><div class="ded-rv "><p class="ar lead">إلى دفعةٍ كان عنوانها الصمود، وشعارها العزم والإصرار.</p></div><div class="ded-rv "><p class="ar hum">لم يكن طريق الطب سهلاً، ولم تكن الرحلة مجرد محاضرات وامتحانات ودرجات تُضاف إلى السجل الأكاديمي؛ بل كانت سنوات من الاجتهاد، وساعات طويلة من الدراسة، وتحديات احتاجت إلى الصبر والثبات، وربما <mark class="hl">بعض القرارات التي لا يمكن تفسيرها إلا بعد انتهاء الامتحانات! 😂</mark></p></div><div class="ded-rv "><p class="ar hum">قد تختلف الحكايات، وتتعدد المواقف، وتتباين التجارب من شخص إلى آخر، لكن يبقى لكل دفعة طابعها الخاص، وذكرياتها التي لا تتكرر، ولحظاتها التي تستحق أن تُحفظ <mark class="hl">بعيداً عن ملفات الـ PDF وجداول الامتحانات</mark>.</p></div><div class="ded-rv "><p class="ar hum">ولعل من أطرف تفاصيل هذا الإهداء أن بعض من تصلهم هذه الكلمات قد يعرفون صاحبها، وربما يحتاج آخرون إلى بعض الوقت لتحديد مصدر هذه المبادرة! ولا بأس بذلك إطلاقاً؛ فليس من الضروري أن تجمعنا معرفة شخصية طويلة حتى نجد سبباً يستحق التقدير. <mark class="hl">ويبدو أن الإهداء قرر أن يسبق التعارف هذه المرة! 😂</mark></p></div><div class="ded-rv "><p class="ar hum">وبعيداً عن كل هذه الرسمية، <mark class="hl">وعن محاولتنا إظهار أن هذا الإهداء مرّ بإجراءات إدارية معقدة</mark>، فإن الحقيقة أبسط من ذلك بكثير:</p></div><div class="ded-rv ded-apprwrap"><div class="ded-appr"><i class="ded-ecg" aria-hidden="true"></i><p class="ar ">هناك دفعات تستحق أن يُقال لها شكراً، وأن يُتمنى لها التوفيق، وأن يُحتفى بما وصلت إليه.</p></div></div><div class="ded-rv ded-batchwrap"><h2 class="ded-batch" dir="ltr"><span>To Batch 52:</span></h2></div><div class="ded-rv "><p class="ar ">قد لا تكون الكلمات كافية لوصف رحلة كاملة، لكنها تظل محاولة بسيطة لتوثيق مرحلة تستحق التقدير.</p></div><div class="ded-rv "><p class="ar ">كل التقدير لجميع أفراد هذه الدفعة، مع أطيب الأمنيات بمستقبل مليء بالنجاح والإنجاز، وأن يكون علمكم طريقاً لنفع الناس، وأن تتركوا أثراً طيباً أينما كنتم.</p></div><div class="ded-rv "><div class="ded-f2" dir="rtl">دفعة 52… فخرٌ بالإنجاز، وعنوانٌ للعزيمة والإصرار.</div></div><div class="ded-rv ded-quotewrap"><blockquote class="ded-quote" dir="ltr"><svg class="qm qm1" viewBox="0 0 48 48" aria-hidden="true"><path d="M20 8C11 11 6 18 6 28v12h16V26H14c0-6 2-9 8-11zM44 8c-9 3-14 10-14 20v12h16V26h-8c0-6 2-9 8-11z"/></svg><p class="en">The journey is not easy, but it is always worth it.</p><svg class="qm qm2" viewBox="0 0 48 48" aria-hidden="true"><path d="M28 40c9-3 14-10 14-20V8H26v14h8c0 6-2 9-8 11zM4 40c9-3 14-10 14-20V8H2v14h8c0 6-2 9-8 11z"/></svg></blockquote></div><div class="ded-rv "><p class="ar offic-ar">وفي الختام، يرجى قبول هذا الإهداء بروح رياضية، وعدم محاولة التحقيق في خلفياته أو أسبابه؛ فقد تم اعتماده وإصداره، و<mark class="hl">أُغلقت جميع أبواب النقاش بشأنه</mark>.</p></div><div class="ded-rv ded-docwrap"><div class="ded-doc" dir="ltr"><span class="ded-seal" aria-hidden="true"><svg viewBox="0 0 64 64"><circle cx="32" cy="32" r="28"/><circle cx="32" cy="32" r="22" class="in"/><path d="M20 33l8 8 16-18"/></svg></span><p class="en">This concludes the official statement. <mark class="hl">No further questions will be entertained. 💀</mark></p></div></div><div class="ded-rv "><p class="en ded-sign" dir="ltr">With respect, appreciation, and a questionable amount of formality.</p></div></article><div class="ded-end" aria-hidden="true"></div></div>`}
(function(){const m=menuView;menuView=function(){return appPage==='dedication'?dedicationView():m.apply(this,arguments)}})();
const DG_ASK=`<h3 id="dgT"><span class="dg-e" aria-hidden="true">😂</span> Wait a minute!</h3><p class="dg-m" id="dgM">Are you sure you want to continue?</p><p class="dg-w" id="dgW">Warning: You might discover something unexpected! 🥺</p><div class="dg-btns two"><button type="button" class="btn primary" id="dgGo" onclick="dedYes()">YES 😎</button><button type="button" class="btn dg-no" onclick="dedNo()">NO 💀</button></div>`;
const DG_NO=`<p class="dg-rel" id="dgT" dir="rtl">😂 الحمد لله، عن شوي ورحنا فيها!</p><div class="dg-btns"><button type="button" class="btn primary" id="dgGo" dir="rtl" onclick="dedAgain()">رجّعني قبل ما أتهور 😂</button></div>`;
function dgPut(h,html){const sh=h.querySelector('.xsheet');sh.classList.remove('swap');void sh.offsetWidth;sh.innerHTML=html;sh.classList.add('swap');try{document.getElementById('dgGo').focus({preventScroll:true})}catch(e){}}
window.dedClose=function(){const g=document.getElementById('dedGate');if(g){g.classList.add('out');setTimeout(()=>g.remove(),200)}document.removeEventListener('keydown',window.__dedKey)};
window.dedGate=function(){
 const old=document.getElementById('dedGate');old&&old.remove();window.__dedBusy=false;
 const ph=document.querySelector('.phone')||document.body,h=document.createElement('div');
 h.id='dedGate';h.className='xwrap ded-gate';
 h.innerHTML='<div class="xbk" onclick="dedClose()"></div><div class="xsheet" role="alertdialog" aria-modal="true" aria-labelledby="dgT"></div>';
 ph.appendChild(h);dgPut(h,DG_ASK);
 window.__dedKey=e=>{if(e.key==='Escape'&&!window.__dedBusy)dedClose()};document.addEventListener('keydown',window.__dedKey);
};
window.dedNo=function(){const h=document.getElementById('dedGate');h&&dgPut(h,DG_NO)};
window.dedAgain=function(){const h=document.getElementById('dedGate');h&&dgPut(h,DG_ASK)};
window.dedYes=function(){
 if(window.__dedBusy)return;window.__dedBusy=true;
 const ph=document.querySelector('.phone'),g=document.getElementById('dedGate');
 const rm=(()=>{try{return matchMedia('(prefers-reduced-motion:reduce)').matches}catch(e){return false}})();
 let fl=null;
 const open=()=>{
  try{g&&g.remove()}catch(e){}document.removeEventListener('keydown',window.__dedKey);
  window.__dedSeen=false;appPage='dedication';renderAppDemo();
  requestAnimationFrame(()=>{const e=document.getElementById('phoneContent');e&&(e.scrollTop=0);document.querySelectorAll('.app-scroll').forEach(x=>x.scrollTop=0)});
  if(fl&&fl.animate){const a=fl.animate([{opacity:1},{opacity:0}],{duration:rm?160:760,easing:'cubic-bezier(.4,0,.2,1)',fill:'forwards'});a.onfinish=()=>{fl.remove();window.__dedBusy=false}}
  else{fl&&fl.remove();window.__dedBusy=false}
  setTimeout(()=>{try{fl&&fl.remove()}catch(e){}window.__dedBusy=false},1600)};
 if(!ph||!ph.animate){open();return}
 fl=document.createElement('div');fl.className='ded-flash';fl.setAttribute('aria-hidden','true');fl.innerHTML='<i></i><b></b>';ph.appendChild(fl);
 g&&g.classList.add('leaving');
 const t=rm?140:380;
 fl.animate([{opacity:0},{opacity:1}],{duration:t,easing:'ease-out',fill:'forwards'});
 if(!rm){fl.firstChild.animate([{transform:'scale(.3)',opacity:.2},{transform:'scale(1.15)',opacity:1}],{duration:t+120,easing:'cubic-bezier(.22,.8,.24,1)',fill:'forwards'});
  fl.lastChild.animate([{transform:'scale(.2)',opacity:.9},{transform:'scale(3)',opacity:0}],{duration:t+520,easing:'cubic-bezier(.22,.8,.24,1)',fill:'forwards'})}
 setTimeout(open,t);
};
/* scroll-triggered reveals: each block plays once */
function dedInit(){
 const pg=document.querySelector('.ded-pg');if(!pg)return;
 const items=[...pg.querySelectorAll('.ded-rv')];
 if(window.__dedSeen||!('IntersectionObserver' in window)){items.forEach(e=>e.classList.add('in'));pg.classList.add('ded-js');return}
 window.__dedSeen=true;pg.classList.add('ded-js');
 const io=new IntersectionObserver(es=>{es.forEach(en=>{if(en.isIntersecting){en.target.classList.add('in');io.unobserve(en.target)}})},{threshold:.14,rootMargin:'0px 0px -6% 0px'});
 items.forEach(e=>io.observe(e));
 setTimeout(()=>items.forEach(e=>{if(!e.classList.contains('in')){const r=e.getBoundingClientRect();if(r.top<innerHeight*1.2&&r.bottom>0)e.classList.add('in')}}),60);
}
(function(){const r=renderAppDemo;renderAppDemo=function(){const x=r.apply(this,arguments);if(appPage==='dedication'){try{dedInit()}catch(e){console.error(e)}}return x}})();
/* smooth return */
(function(){const nb=window.navBack;window.navBack=function(){
 const p=document.querySelector('.ded-pg');
 if(appPage!=='dedication'||!p||window.__dedLeaving){return nb.apply(this,arguments)}
 window.__dedLeaving=true;p.classList.add('ded-leave');
 setTimeout(()=>{window.__dedLeaving=false;nb.apply(window,[])},260)}})();
